UPDATE level SET map_data = JSON_SET(map_data, '$.boss.intro', CAST('["Сто лет тут никого не было. И вот - железный гость с пустыми руками.","Меня зовут Древень. Я помню, как твой создатель рубил на этом месте просеку. Не жаловался.","Дверь на поляне заперта. Ключи я разбросал сам, и один из них настоящий. Остальные слепил на скорую руку.","Ошибёшься на фальшивку - минус жизнь. Не обижайся: у меня по честному, но не по доброму.","Настоящий ключ - тогда бей ракетой. Я не из тех, кто умирает от одного вежливого стука.","Запомни правило: отвечаю по клетке, с которой ты стрелял. Двигайся, железо. Деревья тоже умеют ходить.","После попадания я меняю поляну. Ищи заново: я не мишень, я лес.","И следи за кронами. Когда дерево решит упасть, у тебя будет пара шагов, чтобы уйти."]' AS JSON), '$.boss.key_line', CAST('"Тот самый. Но выход откроется после боя - таков уговор. Не мой, но я его держу."' AS JSON), '$.boss.fake_key_line', CAST('"Фальшивка. Я лепил её из коры и намерения - и ты купился."' AS JSON), '$.boss.hit_line', CAST('"Тепло. Ещё несколько таких - и я начну тебя уважать."' AS JSON), '$.boss.defeat_line', CAST('"Хорошо. Дверь наверху: я переставил её, пока ты целился. Не привыкай."' AS JSON), '$.boss.player_defeat_line', CAST('"Лес закрывает поляну. Начинай с порога - я не обижусь, у меня времени много."' AS JSON), '$.boss.charge_line', CAST('"Заряжаюсь по твоей клетке. Уходи: я не промахиваюсь дважды из вежливости."' AS JSON), '$.boss.shot_line', CAST('"Есть. Запомни эту клетку - она была твоей."' AS JSON), '$.boss.miss_line', CAST('"Мимо. Ты учишься быстрее, чем я старею."' AS JSON), '$.boss.mark_line', CAST('"Прожог на клетке {cell}: следующий залп накроет её и соседей. Уходи далеко, а не на шаг."' AS JSON), '$.boss.mark_shot_line', CAST('"Метка дождалась. Ты остался в ней - значит, решил, что я шутил."' AS JSON), '$.boss.mark_miss_line', CAST('"Вышел из метки. Иногда железо бывает умнее леса."' AS JSON), '$.boss.key_hint_line', CAST('"Настоящий ключ лежит {direction} меня. Остальные я сделал так, чтобы в них верили."' AS JSON), '$.boss.relocate_line', CAST('"Пробил кору - меняю поляну. Ищи: лес большой, а ты маленький."' AS JSON), '$.boss.step_line', CAST('"Отступаю между стволами. Деревья не догоняют - они обходят."' AS JSON), '$.boss.rage_line', CAST('"Последняя жизнь. Теперь шагаю на каждое твоё действие, а деревья падают без предупреждения."' AS JSON), '$.boss.hazard_line', CAST('"Крона затрещала: дерево падает на клетку {cell}. Оно росло двести лет - тебе хватит двух шагов."' AS JSON)) WHERE level_id = 6;
UPDATE level SET map_data = JSON_SET(map_data, '$.boss.intro', CAST('["Скорпион-хан. Ты пришёл за дверью - я торгую дверями.","Пять ключей, четыре обманки. Обманка жалит дважды: две жизни. Такова цена воздуха в моих песках.","Настоящий ключ - и тогда стреляй. Панцирь старый, но он ещё никого не пустил просто так.","Попал - ухожу за дюну, ищи заново. Обида? Нет. Так учат.","Бью туда, откуда ты стрелял. Значит, твоя клетка - твоя память; не оставляй её себе на память.","Буря приходит не сразу: две клетки в ряд. Ушёл с линии - остался в игре.","Победишь - отдам выход. Проиграешь - останешься здесь работать. У меня не хватает слуг."]' AS JSON), '$.boss.key_line', CAST('"Нашёл. Не радуйся: ключ открывает бой, а не дверь."' AS JSON), '$.boss.fake_key_line', CAST('"Обманка. Две жизни - и это ещё вежливо: я мог взять песком."' AS JSON), '$.boss.hit_line', CAST('"Ты попал?! Двадцать лет панцирь не знал такого. Запишу тебя на память."' AS JSON), '$.boss.defeat_line', CAST('"Бери выход, путник. Дверь - не подарок, а долг: ты мне теперь должен за урок."' AS JSON), '$.boss.player_defeat_line', CAST('"Пески забрали тебя. Я не злюсь - я уже выбираю, что сделать из тебя."' AS JSON), '$.boss.charge_line', CAST('"Навожу бурю на твою клетку. Песок не прощает стоячих."' AS JSON), '$.boss.shot_line', CAST('"Есть. Дыши теперь тише."' AS JSON), '$.boss.miss_line', CAST('"Ветер унёс залп. Ты двигался - значит, ты меня понял."' AS JSON), '$.boss.mark_line', CAST('"Отметил клетку {cell}: буря ляжет на неё и на соседей. Прыжок на шаг - не бегство."' AS JSON), '$.boss.mark_shot_line', CAST('"Метка сработала. Ты поверил, что я передумал."' AS JSON), '$.boss.mark_miss_line', CAST('"Вышел из зоны. Неожиданно. Начинаю тебя уважать, железо."' AS JSON), '$.boss.key_hint_line', CAST('"Настоящий ключ зарыт {direction} меня. Остальные я положил так, чтобы ты устал думать."' AS JSON), '$.boss.relocate_line', CAST('"Панцирь треснул - ухожу за дюну. Догоняй: в песках догоняют те, кто выживает."' AS JSON), '$.boss.step_line', CAST('"Лапы перебирают раскалённый песок. Я не отступаю - я выбираю, откуда ударить."' AS JSON), '$.boss.rage_line', CAST('"Жажда крови. Иду на каждое твоё действие, буря ложится шире. Торопись, пока я добрый."' AS JSON), '$.boss.hazard_line', CAST('"Небо желтеет: буря идёт на клетку {cell} и на соседнюю справа. Две клетки - два шага."' AS JSON)) WHERE level_id = 12;
UPDATE level SET map_data = JSON_SET(map_data, '$.boss.intro', CAST('["Здесь всё замерзает, даже время. Ты - первое тёплое за сорок зим.","Пять ключей на снегу. Один я оставила настоящим, остальные заморозила на память.","Мои чары держат твою перезарядку: три действия между выстрелами. Торопиться тут некуда.","Найди ключ, дождись заряда и стреляй. Мне интересно, что у тебя внутри: решимость или батарейка.","Отвечаю залпом в клетку, откуда ты стрелял. Я не повторяю дважды - я запоминаю.","Попал - ухожу на другой гребень. Лёд не спорит, лёд ждёт.","Лавина не мгновенна: три клетки в ряд. Стоять на линии - всё равно что лечь под неё самому."]' AS JSON), '$.boss.key_line', CAST('"Ключ у тебя. Трон ещё закрыт: сначала покажи, на что способен тёплый."' AS JSON), '$.boss.fake_key_line', CAST('"Ловушка. Мороз забирает жизнь молча, в отличие от тебя."' AS JSON), '$.boss.hit_line', CAST('"Трещина. Ещё одна - и я вспомню, как звали того, кто меня собрал."' AS JSON), '$.boss.defeat_line', CAST('"Ты растопил мой трон. Забери выход - я уже скучаю по твоему теплу."' AS JSON), '$.boss.player_defeat_line', CAST('"Холод победил, как всегда. Бой начнётся заново: у меня вечность, у тебя - жизни."' AS JSON), '$.boss.charge_line', CAST('"Лёд под тобой трещит. Я целюсь в твою последнюю клетку."' AS JSON), '$.boss.shot_line', CAST('"Сосулька пробила корпус. Не двигайся - так больнее."' AS JSON), '$.boss.miss_line', CAST('"Снег принял удар. Ты ушёл - я не прощаю, но отмечаю."' AS JSON), '$.boss.mark_line', CAST('"Метка на клетке {cell}: залп накроет её и обе соседние. Три клетки - три шага, не меньше."' AS JSON), '$.boss.mark_shot_line', CAST('"Ты остался в метке. Я думала, ты умнее мороза."' AS JSON), '$.boss.mark_miss_line', CAST('"Вышел из-под метки. Разморожу для тебя одно правило."' AS JSON), '$.boss.key_hint_line', CAST('"Настоящий ключ замёрз {direction} меня. Прочие выглядят одинаково - так задумано."' AS JSON), '$.boss.relocate_line', CAST('"Трон остыл - ищу новый гребень. Догоняй по льду: он не держит торопливых."' AS JSON), '$.boss.step_line', CAST('"Королева скользит, а не ходит. Разница станет явна, когда догонишь."' AS JSON), '$.boss.rage_line', CAST('"Метель крепчает. Иду на каждое твоё действие, лавины сходят чаще. Решайся, огоньёк."' AS JSON), '$.boss.hazard_line', CAST('"Снежная шапка треснула: доска идёт на клетку {cell} и на обе соседние. Это линия, а не точка."' AS JSON)) WHERE level_id = 18;
UPDATE level SET map_data = JSON_SET(map_data, '$.boss.intro', CAST('["Магмовый титан. Я кую тут с тех пор, как земля была горячей и вежливой.","Броня крепкая: пять попаданий, не меньше. Не считай вслух - я уже считал.","Пять ключей в камнях, один настоящий. Остальные я выкинул из кузни, но не подальше.","Найди, заряди ракету и стреляй. Только не подходи близко: я не обнимаю, я палю.","Попадёшь - бью по клетке, откуда ты стрелял. Сменить место - не трусость, а ремесло.","Попал - ухожу на новый выступ. Догоняй, сменщик.","Пол дырявый: фонтан бьёт не сразу. Уходи с намеченной клетки, пока она твоя."]' AS JSON), '$.boss.key_line', CAST('"Нашёл. Дверь откроется после боя: я не отдаю выход за находчивость, отдаю за работу."' AS JSON), '$.boss.fake_key_line', CAST('"Обманка. Лава жжёт - и это мягче, чем мои слова."' AS JSON), '$.boss.hit_line', CAST('"Искры летят. Кузнечный удар: больно, но полезно."' AS JSON), '$.boss.defeat_line', CAST('"Моя магма остыла. Бери выход и знай: теперь кузня на тебе."' AS JSON), '$.boss.player_defeat_line', CAST('"Лава забрала тебя. Жаль: я уже присматривал тебе наковальню."' AS JSON), '$.boss.charge_line', CAST('"Навожу на твою клетку. Уходи: я не работаю по пустому месту."' AS JSON), '$.boss.shot_line', CAST('"Есть. Так проверяют прочность заготовки."' AS JSON), '$.boss.miss_line', CAST('"Промах. Ты ушёл - значит, материал живой."' AS JSON), '$.boss.mark_line', CAST('"Метка на клетке {cell}: следующий залп возьмёт её и соседей. Уходи далеко, тут жарко даже мне."' AS JSON), '$.boss.mark_shot_line', CAST('"Остался в метке. Плохая заготовка."' AS JSON), '$.boss.mark_miss_line', CAST('"Вышел из зоны. Годится. Продолжаем."' AS JSON), '$.boss.key_hint_line', CAST('"Настоящий ключ раскалён {direction} меня. Остальные - пепел, но на вид не отличить."' AS JSON), '$.boss.relocate_line', CAST('"Жерло под мной остыло - ухожу на выступ. Догоняй: смена не опаздывает."' AS JSON), '$.boss.step_line', CAST('"Титан тяжело переступает камни. Не спеши: я тут навсегда, никуда не денусь."' AS JSON), '$.boss.rage_line', CAST('"Извержение! Шагаю на каждое твоё действие, фонтаны бьют чаще. Последняя жизнь - последняя правда."' AS JSON), '$.boss.hazard_line', CAST('"Кора под тобой трескается: фонтан бьёт из клетки {cell}. Дыра в полу - твоя проблема, не моя."' AS JSON)) WHERE level_id = 24;
